-- Book of Magic: Bio-Wizard weapons, restraints and containment (printed 257-279)
-- 39 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~109-book-of-magic-bio-wizard-weapons-and-restraints.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('demon-claw-blade', 'Demon Claw Blade', 'rifts', 'magic', 7, 5000000, 'Five to eight million credits', '6D6 M.D.; double damage to supernatural creatures of good alignment', 1, 'melee', NULL, NULL, NULL, NULL, 100, 'Splugorth Bio-Wizard weapon: a jagged pitch-black blade on a red hilt, also made as an axe, sword, other large blade or a set of claws; knives have half the stats. +1 to strike and parry. 100 M.D.C., damaged only when specifically targeted, regenerating 2D6 M.D.C. per day.', 'Rifts Book of Magic p.257', NULL),
  ('dragonfire-sword', 'Dragonfire Sword', 'rifts', 'magic', 7, 2000000, 'Two to four million credits', '1D4x10+8 M.D.; double damage to creatures vulnerable to fire. Fire Gout 6D6+6 M.D.', 1, 'melee; Fire Gout 180 feet (54.9 m), Circle of Flame 10 foot (3 m) radius, Fuel Flame 100 feet (30.5 m)', '60 P.P.E., regenerating 20 per day; full recharge at a nexus point or stone pyramid', 'Two spell attacks per melee; sword strikes equal to hand to hand attacks', NULL, NULL, 200, 'Splugorth Bio-Wizard sword sheathed in mystic flame, made from the bones of fire demons. Casts as a fifth level mage: Fire Gout (20 P.P.E.), Circle of Flame (10 P.P.E., 6D6 S.D.C.) and Fuel Flame (5 P.P.E.). 200 M.D.C., damaged only when specifically targeted, regenerating 2D6 M.D.C. per day.', 'Rifts Book of Magic p.257', NULL),
  ('entity-domination-staff', 'Entity Domination Staff', 'rifts', 'magic', 10, 1000000, 'Between 1 and 2 million credits', '2D6 M.D. as a blunt weapon', 1, 'melee', 'Four possession attempts per 24 hours; each costs the user 1 P.P.E. or 4 I.S.P.', NULL, NULL, NULL, 100, 'Entity Bio-Wizard staff holding a Possessing Entity. Four times a day the user releases it to possess one target of his choice (standard save vs possession) and commands it for up to six hours; a failed attempt returns the entity to the staff for six hours. 100 M.D.C., damaged only by a called shot; destroying it frees the entity.', 'Rifts Book of Magic p.257-258', NULL),
  ('entity-ectoplasmic-net-launcher', 'Entity Ectoplasmic Net Launcher', 'rifts', 'magic', 20, 75000, '75,000+ credits', 'None; ensnares the target in an ectoplasmic net', 0, '800 feet (244 m)', 'One net per 40 I.S.P. or 10 P.P.E.; stores a maximum of five nets', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, 60, 'Entity Bio-Wizard bazooka-style weapon, usually powered by a Poltergeist. The net has 30 M.D.C., takes one quarter damage from conventional weapons and full damage from magic and psionics, and lasts 4D6 minutes; a combined supernatural P.S. of 30 or higher breaks it within one melee. The launcher has 60 M.D.C., damaged only by a called shot.', 'Rifts Book of Magic p.258', NULL),
  ('entity-fear-pistol', 'Entity Fear Pistol', 'rifts', 'magic', 3, 50000, '50,000 credits', 'None; fear', 0, '400 feet (122 m)', 'One shot per 4 I.S.P. or 1 P.P.E.; stores a maximum of ten shots', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, 35, 'Entity Bio-Wizard pistol, usually powered by a Haunting Entity. The target has a 01-60% chance of retreating unless he saves vs psionics; one who fails but holds his ground is -2 to strike and -4 to parry and dodge for 1D4 minutes. 35 M.D.C., damaged only by a called shot.', 'Rifts Book of Magic p.258', NULL),
  ('entity-kinetic-staff', 'Entity Kinetic Staff', 'rifts', 'magic', 12, 3000000, 'About three million credits, depending on the seller and market conditions', '2D6 M.D. as a blunt weapon; Telekinetic Bolts 1D4 M.D. each', 1, '500 feet (152.4 m) for the telekinetic bolts; other powers as a sixth level psionic', '60 I.S.P., regenerating 10 per hour; can also draw I.S.P. and P.P.E. from other people', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, 100, 'Entity Bio-Wizard staff holding three Tectonic Entities. Powers: Telekinetic Bolts (2 I.S.P.), Telekinesis: Super (10 I.S.P. per 100 lbs/45 kg) and Telekinetic Force Field (30 I.S.P.), the last two at sixth level proficiency. 100 M.D.C., damaged only by a called shot; destroying it frees the entities.', 'Rifts Book of Magic p.258', NULL),
  ('entity-paralysis-rifle', 'Entity Paralysis Rifle', 'rifts', 'magic', 12, 100000, '100,000+ credits', 'None; paralysis', 0, '600 feet (183 m)', 'One blast per 8 I.S.P. or 2 P.P.E.; stores a maximum of ten blasts', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, 60, 'Entity Bio-Wizard rifle using the Bio-Manipulation of a Syphon or Possessing Entity. A target who fails to save vs psionics is paralyzed from head to toe for 1D4 minutes. 60 M.D.C., damaged only by a called shot.', 'Rifts Book of Magic p.258', NULL),
  ('entity-pain-inducer', 'Entity Pain Inducer', 'rifts', 'magic', 12, 120000, '120,000+ credits', 'None; pain', 0, '600 feet (183 m)', 'One blast per 8 I.S.P. or 2 P.P.E.; stores a maximum of ten blasts', 'Equal to the user''s hand to hand attacks per melee', NULL, NULL, 60, 'Entity Bio-Wizard weapon like the Paralysis Rifle. A target who fails to save vs psionics is -4 to strike, parry and dodge and -30% to Spd for 1D4 minutes. 60 M.D.C., damaged only by a called shot.', 'Rifts Book of Magic p.258', NULL),
  ('entity-tk-rifle', 'Entity TK Rifle', 'rifts', 'magic', 10, 150000, '150,000 credits and up', '4D6 M.D. per blast', 1, '2000 feet (610 m)', 'Two shots per 4 I.S.P. or 1 P.P.E.; stores a maximum of 25 shots', 'Equal to the user''s hand to hand attacks per melee; each blast counts as one attack', NULL, NULL, 60, 'Entity Bio-Wizard rifle firing telekinetic bolts, powered by a Tectonic Entity. +1 to strike on an aimed shot. 60 M.D.C., damaged only by a called shot.', 'Rifts Book of Magic p.258', NULL),
  ('eylor-assault-staff', 'Eylor Assault Staff', 'rifts', 'magic', 30, 30000000, 'Generally not available on the open market; 30 to 50 million credits when sold', '4D6 M.D. as a blunt weapon, or 1D4x10+8 when enchanted with the Lightblade spell', 1, 'Varies with the spell cast', '220 P.P.E., regenerating 40 per hour; each spell up to four times per 24 hours', 'Four spells per melee; each casting counts as one melee action', NULL, NULL, 300, 'Splugorth staff with two Eyes of Eylor and no intelligence of its own. Casts as an eighth level spell caster (save 14 or higher): Thunderclap (5 P.P.E.), Fire Ball (10), Call Lightning (15), Orb of Cold (6), Fire Gout (20), Power Bolt (20), Sub-particle Acceleration (20), Lightblade (20), Ballistic Fire (25) and Invincible Armor (30). 300 M.D.C., hit only by a called shot at -2, recovering 2D4x10 M.D.C. per day; the linked owner takes five points of damage for every point the staff takes.', 'Rifts Book of Magic p.259', NULL),
  ('eylor-exploration-staff', 'Eylor Exploration Staff', 'rifts', 'magic', 20, 10000000, 'Generally not available on the open market; 10 to 20 million credits when sold', '3D6 M.D. as a blunt weapon plus the user''s supernatural P.S. punch damage', 1, 'Self only for all spells', '150 P.P.E., regenerating 20 per hour; up to 18 spells per day', 'Up to three spells per melee round; each casting counts as one melee action', NULL, NULL, 150, 'Intelligent Splugorth staff that protects its linked owner from hostile environments. Casts as an eighth level spell caster: Impervious to Radiation (50 P.P.E.), Impervious to Vacuum (80), Impervious to Ocean Depths (75), Impervious to Energy (20), Impervious to Fire (5), Impervious to Cold (10), Impervious to Poison (5), Heal Self (20; 3D6 S.D.C. and 1D6 Hit Points, or 1D4 M.D.C.), Negate Poison (5), Breathe without Air (5) and Invincible Armor (30; 200 M.D.C.). 150 M.D.C., hit only by a called shot at -2, recovering 1D4x10 M.D.C. per day; the owner takes ten points of damage for every M.D. the staff takes.', 'Rifts Book of Magic p.259-260', NULL),
  ('eylor-shield-of-invincibility', 'Eylor Shield of Invincibility', 'rifts', 'magic', 10, 8000000, 'Eight to twelve million credits', '2D4 M.D. on a shield strike', 1, 'melee; 800 feet (244 m) for targeted deflect attacks', '100 P.P.E., regenerating 10 per hour; full recharge at a nexus point or stone pyramid', NULL, NULL, NULL, 300, 'Splugorth shield empowered by a small Eye of Eylor. +2 to parry. Magic as a sixth level spell caster: Speed Weapon (100 P.P.E.; the bearer may try to parry every attack directed at him, long-range attacks on a straight roll, surprise attacks not at all), Targeted Deflection (15 P.P.E.) and Deflect (10 P.P.E.), the last two working only on the shield. 300 M.D.C., regenerating 10 M.D.C. per minute; not linked to its owner and no intelligence.', 'Rifts Book of Magic p.261', NULL),
  ('eylor-mace', 'Eylor Mace (Mace of Eylor)', 'rifts', 'magic', 10, 10000000, 'Generally not available on the open market; 10 to 30 million credits when sold', '1D6x10 M.D. per strike plus the wielder''s supernatural P.S. damage (no P.S. damage when thrown)', 1, 'melee; thrown up to 500 feet (152 m) and returns', '100 P.P.E., regenerating 20 per hour; each spell up to two times per 24 hours', 'Two spells per melee; each casting counts as one melee action', NULL, NULL, 250, 'Splugorth mace with an Eye of Eylor, psionically linked to its owner and returning when thrown or dropped. +1 to strike thrown or in hand to hand. Casts as an eighth level spell caster (save 14 or higher): Thunderclap (5 P.P.E.), Call Lightning (15), Wind Rush (20), Electric Arc (8) and Lightning Arc (30). 250 M.D.C., recovering 1D4x10 M.D.C. per day; damage to it does not carry over to the owner.', 'Rifts Book of Magic p.262', NULL),
  ('faerie-blizzard-staff', 'Faerie: Blizzard Staff', 'rifts', 'magic', 20, 10000000, '10 to 12 million credits; not often available even in Atlantis and other Splugorth markets', '2D6 M.D. as a blunt weapon, double to creatures vulnerable to cold; Shards of Ice 1D4 M.D.', 1, 'Varies with the spell; Shards of Ice 150 feet (45.7 m)', 'Unlimited; powered by the constantly renewing energy of the enslaved Faerie', NULL, NULL, NULL, 60, 'Faerie Bio-Wizard staff powered by two bound Frost Pixies. Water Warlock spells at fifth level proficiency: Snowstorm (once per hour), Encase in Ice (once per melee), Wall of Ice (once per melee) and Shards of Ice (as often as the user has attacks; double damage to creatures vulnerable to ice). 60 M.D.C. plus 30 for the Faerie housing, damaged only when attacked directly.', 'Rifts Book of Magic p.262-263', NULL),
  ('faerie-dark-lightning', 'Faerie: Dark Lightning', 'rifts', 'magic', 50, 2000000, '2-6 million credits; poor availability even in Atlantis', '1D4x10 M.D.; on a failed save vs magic (14 or higher) an additional 4D6 direct to Hit Points, or M.D.C. for a Mega-Damage creature', 1, '600 feet (183 m)', 'Unlimited; powered by the constantly renewing energy of the enslaved Faerie', 'Four per melee round; each shot counts as one melee action', NULL, NULL, 60, 'Huge Faerie Bio-Wizard handgun powered by a Bogie; two hands are needed (otherwise -3 to strike) unless the shooter has a P.S. of 24 or higher. A target who fails the save is also -2 to all combat bonuses, -1 attack per melee and -30% to skill performance for 1D4 minutes. 60 M.D.C., damaged only when attacked directly.', 'Rifts Book of Magic p.263', NULL),
  ('faerie-floodwater-pistol-or-rod', 'Faerie: Floodwater Pistol or Rod', 'rifts', 'magic', 4, 120000, '120,000 credits; good availability in Atlantis, the Gargoyle Empire, New Phoenix and most Splugorth markets', 'A stream of water: 6D6 Hit Point damage to vampires, 4D6 M.D. to other creatures vulnerable to water', 1, '400 feet (122 m)', 'Unlimited; powered by the constantly renewing energy of the enslaved Faerie', 'Four per melee round; each shot counts as one melee action', NULL, NULL, NULL, 'Faerie Bio-Wizard anti-vampire weapon powered by an enslaved Water Sprite. 25 M.D.C. as a pistol, 40 as a staff; damaged only when attacked directly, and attackers are -1 to strike.', 'Rifts Book of Magic p.263', NULL),
  ('faerie-vinewrapper-pistol-or-rod', 'Faerie: Vinewrapper Pistol or Rod', 'rifts', 'magic', 5, 225000, '225,000 credits on Atlantis, double to quadruple elsewhere', 'None; entangling vines', 0, '500 feet (152 m)', 'Unlimited; powered by the constantly renewing energy of the enslaved Faerie', 'Four per melee round; each shot counts as one melee action', NULL, NULL, NULL, 'Faerie Bio-Wizard weapon powered by a Green Wood Faerie or Tree Sprite. Vines hold the target for 2D4 melee rounds unless broken by a supernatural P.S. of 30 or 5D6 M.D. inflicted on them; the victim can use only his own strength, though others may use weapons to help. 25 M.D.C. as a pistol, 40 as a staff; damaged only when attacked directly, and attackers are -1 to strike.', 'Rifts Book of Magic p.263-264', NULL),
  ('faerie-windstream-pistol-or-rod', 'Faerie: Windstream Pistol or Rod', 'rifts', 'magic', 5, 200000, '200,000 credits at Atlantis, double most other places', 'None; a blast of wind', 0, '800 feet (244 m)', 'Unlimited; powered by the constantly renewing energy of the enslaved Faerie', 'Four per melee round; each shot counts as one melee action', NULL, NULL, NULL, 'Faerie Bio-Wizard weapon powered by a Silver Bell Faerie or Wind Puff Sprite. The wind knocks over anything weighing less than 200 lbs (90 kg); anyone knocked down loses initiative and one melee action. It disperses gas completely in half a melee round. 25 M.D.C. as a pistol, 40 as a staff; damaged only when attacked directly, and attackers are -1 to strike.', 'Rifts Book of Magic p.264', NULL),
  ('faerie-ppe-battery', 'Faerie P.P.E. Battery', 'rifts', 'magic', 3, 60000000, '60 million credits and up; rare even in Atlantis', NULL, 0, NULL, '2D6+50 P.P.E., regenerating 2D6 per hour', NULL, NULL, NULL, 35, 'Bio-Wizard battery housing an enslaved Faerie. It can be fitted to almost any Techno-Wizard weapon or device: most light weapons can fire 100 shots per hour and heavy weapons perhaps 50. On a one-man ley line vehicle it allows travel away from ley lines at 20% of normal speed with no other features working.', 'Rifts Book of Magic p.264', NULL),
  ('fang-dagger', 'Fang Dagger', 'rifts', 'magic', 5, 200000, '200,000 credits', '4D6 M.D.', 1, 'melee', NULL, NULL, NULL, NULL, 100, 'Called The Fang: one of the cheapest Splugorth Bio-Wizard weapons, usually a sword but also made as a scythe or pole arm with the same stats; knives and daggers have all stats halved. 100 M.D.C., damaged only when specifically targeted, regenerating 2D6 M.D.C. per day.', 'Rifts Book of Magic p.264', NULL),
  ('living-whip', 'Living Whip', 'rifts', 'magic', 2, 350000, '350,000 credits; one million credits as a Bio-Wizard implant', '3D6 M.D. per strike', 1, 'melee, with a reach of 8 feet (2.4 m)', NULL, NULL, NULL, NULL, 75, 'Splugorth Bio-Wizard baton that stretches into a living eight foot whip on a mental command. +1 to initiative, +1 to strike and entangle, +2 to disarm. 75 M.D.C.; 25 M.D. severs part of it; it regenerates 4D6 M.D.C. per hour and lost pieces regrow in 24 hours. Also sold as an implanted weapon limb at the shoulder or under the forearm, with the same combat abilities.', 'Rifts Book of Magic p.264', NULL),
  ('venom-blade', 'Venom Blade', 'rifts', 'magic', 5, 600000, '600,000 credits, half for daggers and knives', '2D6 M.D. short sword, 1D6 M.D. dagger, plus venom on a stabbing strike', 1, 'melee', 'Ten doses of venom (five for a dagger), regenerating one per hour', NULL, NULL, NULL, 80, 'Splugorth dagger or short sword with twin curved blades that injects venom on a stabbing strike (save 14 or higher). Each weapon has one venom: Lethal (1D6 M.D., or 1D6x10 to S.D.C. beings, per melee for 1D4 melee rounds), Paralysis (Spd and combat bonuses halved, no initiative, 1D4 melee rounds), Fire (-5 to combat bonuses, Spd -30%, skills -20%, 1D6 melee rounds) or Extreme Dizziness (combat bonuses reduced to zero and a 01-40% chance of falling every ten feet/3 m). Further strikes add duration, not damage. 80 M.D.C. (40 for a dagger, which also weighs half), regenerating 1D6 M.D.C. per hour.', 'Rifts Book of Magic p.267', NULL),
  ('conventional-mega-damage-shackles', 'Conventional Mega-Damage Shackles', 'rifts', 'gear', NULL, 100, '100 to 400 credits for light S.D.C. shackles, 500 to 1000 for heavy S.D.C. or light M.D.C., 2000 to 4000 for medium M.D.C., 5000 to 10,000 for heavy M.D.C.; an advanced lock adds 10% to 25%', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Wrist, arm and ankle shackles joined by chain, in five grades: light S.D.C. (40 to 80 S.D.C.), heavy S.D.C. (100 to 500 S.D.C., or 1-5 M.D.C.), light M.D.C. (5 to 10 M.D.C.), medium M.D.C. (20-30 M.D.C.) and heavy M.D.C. (40-50 M.D.C.). Advanced locks give -10% to lock picking, the most advanced -35% to Pick Locks or Locksmith.', 'Rifts Book of Magic p.274', NULL),
  ('d-shackles', 'D-Shackles', 'rifts', 'magic', NULL, 2300000, 'An average of 2.3 million credits (sometimes 10-20% less, more often 10-20% higher); very rare', NULL, 1, NULL, NULL, NULL, NULL, NULL, 30, 'Living Bio-Wizard shackles that raise a dimensional barrier around the captive, blocking all teleportation and dimension warping by magic, psionics or natural power, including attempts from outside to free him. More fragile than other Bio-Wizard shackles and insufficient for a supernatural P.S. of 36 or higher.', 'Rifts Book of Magic p.274-275', NULL),
  ('living-shackles', 'Living Shackles', 'rifts', 'magic', NULL, 50000, '50,000 to 100,000 credits, depending on M.D.C.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'One-piece organic Bio-Wizard shackles with 50 to 100 M.D.C., keyed to the voice or DNA of the registered owner. -90% to Pick Locks and Locksmith, -50% to Escape Artist, impervious to the Escape spell, and they contract tighter if the captive struggles.', 'Rifts Book of Magic p.275', NULL),
  ('microbe-injector', 'Microbe Injector', 'rifts', 'magic', NULL, 500000, '500,000 credits for the Dehibicila injector, 700,000 for the Stasirobes injector, three million for the Dragoncila injector (outlawed in Atlantis)', NULL, 1, NULL, NULL, NULL, NULL, NULL, 30, 'Parasitic Bio-Wizard restraint like a small octopus, attached to the chest or back, that injects a constant dose of one microbe (Dehibicila, Stasirobes or Dragoncila); the symptoms last as long as it is attached.', 'Rifts Book of Magic p.275', NULL),
  ('mouth-wrap', 'Mouth Wrap', 'rifts', 'magic', NULL, 25000, '25,000 credits', NULL, 1, NULL, NULL, NULL, NULL, NULL, 25, 'Bio-Wizard creature that adheres over the mouth, keeping it shut and preventing speech while letting air through; used with other restraints to silence practitioners of magic.', 'Rifts Book of Magic p.275', NULL),
  ('strength-neutralizers', 'Strength Neutralizers', 'rifts', 'magic', NULL, 500000, '500,000 credits', NULL, 1, NULL, NULL, NULL, NULL, NULL, 100, 'Bio-Wizard shackles that turn the captive''s own strength back on him: he can never break free by his own brute strength, nor add it to the efforts of others, though two or more others can pool theirs. Reducing the M.D.C. to zero kills the creature and frees the captive.', 'Rifts Book of Magic p.275', NULL),
  ('techno-wizard-shackles', 'Techno-Wizard Shackles', 'rifts', 'magic', NULL, 40000, '40,000 to 75,000 credits, depending on M.D.C.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Conventional shackles augmented by a Techno-Wizard, with 40 to 80 M.D.C. Attempts to pick or escape them are at -35%, and against the Escape spell they save vs magic on 12 or higher.', 'Rifts Book of Magic p.275', NULL),
  ('energy-bonds', 'Energy Bonds', 'rifts', 'magic', NULL, 65000, '65,000 to 115,000 credits, depending on M.D.C.; the advanced model with the energy field adds 200,000 credits and 20 M.D.C.', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Techno-Wizard shackles impervious to energy, with 50 to 100 M.D.C., used on Bursters, Zappers and others with natural energy expulsion. The advanced model raises an energy field that stops the captive firing energy at all. -35% to being picked or escaped, as Techno-Wizard Shackles.', 'Rifts Book of Magic p.276', NULL),
  ('containment-body-armor', 'Containment Body Armor', 'rifts', 'armor', 30, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, 40, 'Coalition restraint suit of metal alloys and heavy ceramics for magic-using prisoners held more than 12 hours, weighing 30-40 pounds (13.5 to 18 kg) and covering three quarters of the body: arms locked down, hands in mitten-like covers, a featureless helmet that blinds and silences, chained boots. Not environmental. Running speed is one third of normal; swimming, climbing, acrobatics and skills needing hands or arms are impossible. A wearer who manages to cast spends 20% more P.P.E. and rolls per spell: 01-20% damage or effects reduced by 1D4x10%; 21-40% duration reduced by 1D4x10%; 41-60% range reduced by 1D4x10%; 61-80% range and duration both reduced by 20%; 81-00% no additional problem.', 'Rifts Book of Magic p.276-277', NULL),
  ('cs-prisoner-bionic-hands', 'Bionic Hands (CS Prisoner Pacification)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Crude mechanical replacement for one or both hands, a hand and forearm or a whole arm, fitted to magic-using prisoners. P.S. and P.P. of 6; 10 M.D.C. for a hand, 15 for a forearm, 20 for an entire arm and hand; sense of touch 15%. Like any implant it impairs magic (reduced P.P.E., no drawing on ley lines). No price printed. A bio-system replacement on the secondary market costs 50,000-65,000 credits for a hand or 100,000-150,000 for an arm and hand (touch 50%, maximum P.S. 8 and P.P. 10, -5% skill penalty, 25 S.D.C.) and restores full use of magic.', 'Rifts Book of Magic p.277', NULL),
  ('cs-lock-jaw-implant', 'Lock Jaw (CS Prisoner Implant)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implant that locks the jaw muscles so the prisoner cannot open his mouth or speak clearly. Only simple first and second level spells can be cast, spoken slowly, using up four melee actions (about 15 seconds). Switched by an external hand-held control. No price printed.', 'Rifts Book of Magic p.277', NULL),
  ('cs-optic-blinder-implant', 'Optic Blinder (CS Prisoner Implant)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implant that scrambles optic signals to the brain and blinds the prisoner, switched on and off by an external control. No line-of-sight spells, and the usual -9 to strike, parry and dodge for blindness. No price printed.', 'Rifts Book of Magic p.277', NULL),
  ('cs-pain-inflictor-implant', 'Pain Inflictor (CS Prisoner Implant)', 'rifts', 'cybernetics', NULL, NULL, NULL, '1D4 per melee round of pain, to S.D.C. then Hit Points', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implant in the head or spine that racks the prisoner with pain at the flick of a switch: hand to hand attacks and combat bonuses halved, speed reduced by 20%, skills at -30%, and no magic can be cast while in pain. Prolonged use can kill. No price printed.', 'Rifts Book of Magic p.277-278', NULL),
  ('cs-prisoner-id-chip', 'Prisoner I.D. Chip (CS)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implant given to all Coalition prisoners that transmits name, rank, serial number, prisoner I.D. number and date captured. No price printed.', 'Rifts Book of Magic p.278', NULL),
  ('cs-tracer-implant', 'Tracer Implant (CS)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 0, '60 miles (96 km) in the wilderness; 20 miles (32 km) underground or in urban environments', NULL, NULL, NULL, NULL, NULL, 'Implant along the spine, neck or skull that emits a radio tracking signal, powered by the body so effectively perpetual; shut off only by removing it. Given to most (90%) Coalition prisoners. No price printed.', 'Rifts Book of Magic p.278', NULL),
  ('cs-vocal-cord-neutralizer', 'Vocal Cord Neutralizer (CS Prisoner Implant)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implant that neutralizes the vocal cords: the prisoner can mouth words but utter only grunts, groans and whistles. Used on 80% of magic-using prisoners to prevent spell casting; switched by a hand-held control. No price printed.', 'Rifts Book of Magic p.278', NULL),
  ('cs-white-noise-generator-implant', 'White Noise Generator Implant (CS)', 'rifts', 'cybernetics', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Implant in the back of the head or ear whose noise makes sleep and concentration virtually impossible; only those highly skilled in meditation, with an M.E. of 24 or greater, or of 8th level or higher can block it for 1D4x10 minutes plus 1D6 minutes per level. It stops recovery of P.P.E. and I.S.P., and psionics cost double I.S.P. at half range, duration and damage. After two days: -40% to skills, combat bonuses halved, a spell takes four melee actions. Three to four days: -60% to skills, no combat bonuses, speed and attacks halved, a spell takes 1D4+6 melee actions. After five days: save vs insanity, skills take three times as long at -85%, two attacks per melee, speed and strength reduced by 80%, only 1D4 first and second level spells remembered. Six days and beyond: the victim lasts one day per M.E. point before going permanently insane. Switched by an external hand-held unit. No price printed.', 'Rifts Book of Magic p.278-279', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 39 gear rows are in' AS assertion, count(*) AS got, 39 AS want
